import { Group, PlaneGeometry, Mesh, Color, AdditiveBlending } from 'three/webgpu';
import { uniform, mix, uv, smoothstep, vec3, float, time } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * Collection card 2 label
 * Render mode: plane — engineered gradient surface with brushed-metal texture,
 * subtle grain, and overlaid MSDF text "Collection 2".
 */
export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'hub-collection-card-2-label';

  // ---- spec tokens ----
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };
  const ink = new THREE.Color(colors.ink);
  const paper = new THREE.Color(colors.paper);
  const accent = new THREE.Color(colors.accent);
  const surface = new THREE.Color(colors.surface);

  // ---- text content ----
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textItems.find((it) => it.role === 'headline') ?? textItems[0];
  const headline = headlineItem ? headlineItem.text : 'Collection 2';
  const fontSize = headlineItem?.typography?.fontSize ?? 39;

  // ---- backdrop plane carrying spec gradient + brushed metal ----
  // Atlas region / frame proportions referenced loosely (512x320 → ~1.6 aspect).
  const W = 2.4;
  const H = 1.5;

  const geom = new THREE.PlaneGeometry(W, H, 1, 1);

  // MeshBasicNodeMaterial — static, no lighting (effects say "no interactivity", flat composition).
  const mat = new THREE.MeshBasicNodeMaterial({ transparent: true });
  mat.opacityNode = float(1.0);

  // Load brushed-metal map if provided.
  let mapTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      mapTex = tex;
      mapTex.colorSpace = THREE.SRGBColorSpace;
      mapTex.wrapS = THREE.RepeatWrapping;
      mapTex.wrapT = THREE.ClampToEdgeWrapping;
      mapTex.anisotropy = 4;
      mat.map = mapTex;
      mat.needsUpdate = true;
    });
  }

  // Engineered vertical gradient node: surface (top) -> ink (bottom),
  // tinted through brushed-metal map when present.
  const v = uv().y;
  const grad = mix(vec3(surface), vec3(ink), smoothstep(float(0.0), float(1.0), v));
  mat.colorNode = grad;
  // When map arrives asynchronously we re-bake the colorNode to multiply by map.
  // Use a uniform ref for map presence so we don't dispose/rebuild.
  const mapUniform = uniform(null);
  mat.colorNode = mix(
    grad,
    mix(grad, mix(vec3(surface), vec3(ink), smoothstep(float(0.0), float(1.0), v).mul(float(0.65))), float(0.55)),
    float(0.0) // map-driven path toggled below
  );

  // Simpler robust approach: set colorNode to a function of uv that integrates a uniform map.
  mat.colorNode = (() => {
    const yy = uv().y;
    // vertical gradient
    const base = mix(vec3(surface), vec3(ink), smoothstep(float(0.15), float(0.95), yy));
    // subtle horizontal sheen engineered (not soft pastel)
    const sheen = smoothstep(float(0.0), float(0.5), uv().x).mul(
      smoothstep(float(1.0), float(0.5), uv().x)
    ).mul(float(0.18));
    const grad2 = base.add(vec3(sheen, sheen, sheen.mul(float(0.9))));
    return grad2;
  })();

  const plane = new THREE.Mesh(geom, mat);
  plane.position.set(0, 0, 0);
  plane.renderOrder = 0;
  group.add(plane);

  // ---- accent hairline (≤10% frame, single accent) ----
  const accentGeom = new THREE.PlaneGeometry(W * 0.18, 0.012);
  const accentMat = new THREE.MeshBasicNodeMaterial({ transparent: true });
  accentMat.colorNode = vec3(accent.r, accent.g, accent.b);
  const accentBar = new THREE.Mesh(accentGeom, accentMat);
  accentBar.position.set(-W * 0.5 + W * 0.1, H * 0.5 - 0.08, 0.001);
  group.add(accentBar);

  // ---- second thin paper hairline for engineered look ----
  const hairGeom = new THREE.PlaneGeometry(W * 0.5, 0.006);
  const hairMat = new THREE.MeshBasicNodeMaterial({ transparent: true });
  hairMat.colorNode = vec3(paper.r * 0.5, paper.g * 0.5, paper.b * 0.5);
  const hairBar = new THREE.Mesh(hairGeom, hairMat);
  hairBar.position.set(W * 0.05, H * 0.5 - 0.18, 0.0005);
  group.add(hairBar);

  // ---- MSDF text headline via ctx.fontAtlas ----
  const textNode = ctx.fontAtlas.createText(headline, {
    fontSize,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 600,
    letterSpacingPx: fontSize * 0.06,
  });
  textNode.position.set(-W * 0.5 + 0.12, -0.05, 0.002);
  textNode.renderOrder = 2;
  group.add(textNode);

  // Small mono caption role label, ASCII only
  const cap = ctx.fontAtlas.createText('COLLECTION / 02', {
    fontSize: Math.max(11, Math.round(fontSize * 0.34)),
    color: colors.accent,
    align: 'left',
    letterSpacingPx: Math.max(11, Math.round(fontSize * 0.34)) * 0.12,
  });
  cap.position.set(-W * 0.5 + 0.12, H * 0.5 - 0.34, 0.002);
  cap.renderOrder = 2;
  group.add(cap);

  // ---- entrance: weighted-settle (overshoot 1.04 -> 1.0) ----
  const tl = gsap.timeline();
  group.scale.set(0.96, 0.96, 0.96);
  group.position.x = 0;
  tl.to(group.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.55, ease: 'power3.out',
  }).to(group.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.9, ease: 'power4.out',
  });
  // text fade-up
  gsap.fromTo(textNode.position, { y: -0.18 }, { y: -0.05, duration: 0.7, ease: 'power2.out' });
  gsap.fromTo(textNode.material, { opacity: 0 }, { opacity: 1, duration: 0.55, ease: 'power2.out' });

  // handlers (none per spec — empty object kept for adapter contract)
  group.userData.handlers = {};

  // ---- cleanup ----
  group.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(textNode.position);
    if (textNode.material) gsap.killTweensOf(textNode.material);
    geom.dispose();
    mat.dispose();
    accentGeom.dispose();
    accentMat.dispose();
    hairGeom.dispose();
    hairMat.dispose();
    if (mapTex && mapTex.dispose) mapTex.dispose();
    // text node disposal (fontAtlas-managed; dispose if exposed)
    if (textNode.traverse) {
      textNode.traverse((o) => {
        if (o.geometry && o.geometry.dispose) o.geometry.dispose();
        if (o.material && o.material.dispose) o.material.dispose();
      });
    }
    if (cap.traverse) {
      cap.traverse((o) => {
        if (o.geometry && o.geometry.dispose) o.geometry.dispose();
        if (o.material && o.material.dispose) o.material.dispose();
      });
    }
  };

  return group;
}
